mapper.select:
SELECT * FROM agri_prod_sensor_data
WHERE device_id = #{deviceId}
AND data_time >= #{startTime}
AND data_time <= #{endTime}
ORDER BY data_time DESC

SELECT DATE_FORMAT(data_time, '%Y-%m-%d %H:00:00') AS hour,
       ROUND(AVG(value), 4) AS avgValue,
       COUNT(*) AS sampleCount
FROM agri_prod_sensor_data
WHERE device_id = #{deviceId}
AND data_time >= #{startTime}
AND data_time <= #{endTime}
GROUP BY DATE_FORMAT(data_time, '%Y-%m-%d %H:00:00')
ORDER BY hour

SELECT COUNT(*) AS dataCount,
       ROUND(AVG(value), 4) AS avgValue,

       ROUND(MAX(value), 4) AS `maxValue`,
       ROUND(MIN(value), 4) AS `minValue`,
       MAX(data_time) AS latestTime
FROM agri_prod_sensor_data
WHERE device_id = #{deviceId}
AND data_time >= #{startTime}
AND data_time <= #{endTime}
